//! Run via `npm run api:generate` / `npm run api:check` in frontend/.

use std::path::Path;

use lobotomy_core::view::{Event, Found, Match, MatchKind};
use lobotomyd::gui::protocol::ChangePush;
use serde_json::json;
use ts_rs::{Config, TS};

fn main() -> anyhow::Result<()> {
    // serde_json writes JSON numbers; JSON.parse produces numbers, never JS bigints.
    // Deliberately ignore TS_RS_* environment variables so generation is reproducible.
    let config = Config::new().with_large_int("number");
    let mut output = String::from(
        "// Generated by npm run api:generate. Do not edit.\n\
         // JSON integers are JS numbers and may lose precision above Number.MAX_SAFE_INTEGER.\n\n",
    );
    for declaration in [
        MatchKind::decl(&config),
        Match::decl(&config),
        Found::decl(&config),
        Event::decl(&config),
        ChangePush::decl(&config),
    ] {
        let declaration = declaration.lines().map(str::trim_end).collect::<Vec<_>>().join("\n");
        output.push_str(&format!("export {declaration}\n\n"));
    }
    let output = output.trim_end().to_owned() + "\n";
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../frontend/src/api/generated.ts");
    if std::env::args().any(|arg| arg == "--check") {
        anyhow::ensure!(
            std::fs::read_to_string(&path).ok().as_deref() == Some(&output),
            "GUI types are stale; run npm run api:generate in frontend/"
        );
    } else {
        std::fs::write(path, output)?;
    }

    // Serialize the actual wire types. The frontend script checks these literals against the
    // generated types: enum tags/renames, required nullable fields, arbitrary JSON and numbers.
    let search = Found {
        matches: vec![
            Match { kind: MatchKind::Item, id: "item".into(), seq: Some(1) },
            Match { kind: MatchKind::Message, id: "queued".into(), seq: None },
        ],
        more: false,
    };
    let events: Vec<_> = [json!({ "task_id": "task" }), json!(null), json!([1, "text"]), json!(true)]
        .into_iter()
        .enumerate()
        .map(|(index, payload)| Event {
            seq: if index == 0 { i64::MAX } else { index as i64 },
            kind: "future.changed".into(),
            entity: "task".into(),
            payload,
            command_id: (index == 0).then(|| "command".into()),
            caller: (index == 0).then(|| "user".into()),
            caller_turn_id: None,
        })
        .collect();
    println!(
        "{}",
        json!({
            "search": search,
            "pushes": [
                ChangePush::Events { project: "project", events: &events },
                ChangePush::Thread { project: "angela", role: "Angela", seq: 1 },
            ],
        })
    );
    Ok(())
}
